from dataclasses import dataclass, field
from typing import TypedDict, NotRequired
import attrs, cattrs
@dataclass
class Child:
    x: int
    y: int = 7
@dataclass
class Parent:
    child: Child
    items: list[int] = field(default_factory=list)
    hidden: int = field(default=2, init=False)
for detailed in (True, False):
    c = cattrs.Converter(detailed_validation=detailed, forbid_extra_keys=True)
    r = c.partial_structure({'child': {'x':'1','y':'bad'}, 'items':['bad'], 'extra':1}, Parent)
    assert r.value == Parent(Child(1, 7), []) and r.failed_fields == {'child','items'} and r.errors
    s = r.refine({'child': {'y':'2'}, 'items':['3']})
    assert s.is_complete and s.value == Parent(Child(1,2), [3])
    assert r.failed_fields == {'child','items'}
@attrs.define
class A:
    x: int
    y: int = 4
r = cattrs.BaseConverter().partial_structure({'x':'1'}, A)
assert r.value == A(1,4) and r.failed_fields == {'y'}
class TD(TypedDict):
    x: int
    y: NotRequired[int]
r = cattrs.partial_structure({'x':'1'}, TD)
assert r.value == {'x':1} and r.failed_fields == {'y'}
assert r.refine({'y':'3'}).value == {'x':1, 'y':3}
print('edge cases passed')
